"""Generate ``contracts/openapi.yaml`` from the FastAPI routes in ``services/api``.

Usage:
    uv run python scripts/export_openapi.py           # regenerate
    uv run python scripts/export_openapi.py --check   # CI: fail if out of date
"""

import argparse
import sys

from contract_io import CONTRACTS_DIR, dump_yaml, sync_files

from app.main import create_app

OPENAPI_PATH = CONTRACTS_DIR / "openapi.yaml"


def render() -> str:
    spec = create_app().openapi()
    header = (
        "# GENERATED by scripts/export_openapi.py from services/api routes - do not edit.\n"
        "# Change process: contracts/README.md\n"
    )
    return header + dump_yaml(spec)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if file is out of date")
    args = parser.parse_args()
    rc = sync_files(
        {OPENAPI_PATH: render()}, check=args.check, stale_glob=(CONTRACTS_DIR, "openapi.yaml")
    )
    if rc == 0:
        print("openapi: ok" if args.check else f"openapi: wrote {OPENAPI_PATH}")
    return rc


if __name__ == "__main__":
    sys.exit(main())
